# Generated by unmv. Sources only an unmv helper; mv is unchanged.
function unmv() (
    emulate -L zsh
    local unmv_name=mv unmv_type unmv_value unmv_next unmv_option unmv_path unmv_depth
    local -a unmv_words
    export UNMV_CONTEXT_SHELL=zsh UNMV_CONTEXT_TYPE=unknown
    export UNMV_CONTEXT_COMMAND='' UNMV_CONTEXT_DESCRIPTION=''
    for ((unmv_depth=0; unmv_depth<16; unmv_depth++)); do
        unmv_type=$(builtin whence -w "$unmv_name")
        if [[ $unmv_type == *': alias' ]]; then
            unmv_value=${aliases[$unmv_name]}
            UNMV_CONTEXT_DESCRIPTION+="$unmv_name=$unmv_value; "
            unmv_words=( ${(z)unmv_value} )
            unmv_next=${unmv_words[1]}
            [[ $unmv_next =~ '^[a-zA-Z0-9_./+-]+$' ]] || break
            for unmv_option in "${unmv_words[@]:1}"; do
                [[ $unmv_option =~ '^-[finv]+$' || $unmv_option == --force || $unmv_option == --interactive || $unmv_option == --no-clobber || $unmv_option == --verbose ]] || break 2
            done
            if [[ $unmv_next != "$unmv_name" ]]; then
                unmv_name=$unmv_next
                continue
            fi
            if (( ${+functions[$unmv_name]} )); then
                UNMV_CONTEXT_DESCRIPTION+="${functions[$unmv_name]}"
                break
            fi
        elif [[ $unmv_type == *': function' ]]; then
            UNMV_CONTEXT_DESCRIPTION+="${functions[$unmv_name]}"
            break
        elif [[ $unmv_type != *': command' && $unmv_type != *': hashed' ]]; then
            UNMV_CONTEXT_DESCRIPTION+="unknown command $unmv_name ($unmv_type)"
            break
        fi
        unmv_path=$(builtin whence -p "$unmv_name")
        if [[ -n $unmv_path ]]; then
            UNMV_CONTEXT_TYPE=external
            UNMV_CONTEXT_COMMAND=$unmv_path
            UNMV_CONTEXT_DESCRIPTION+="$unmv_path"
        fi
        break
    done
    command @UNMV_BIN@ "$@"
)
